styles:
@font-face {
  font-family: 'Cormorant Garamond';
  font-style: italic;
  font-weight: 400;
  font-display: swap;
  src: url(/fonts/basilisk-font-0.ttf) format('truetype');
}
@font-face {
  font-family: 'Cormorant Garamond';
  font-style: normal;
  font-weight: 400;
  font-display: swap;
  src: url(/fonts/basilisk-font-1.ttf) format('truetype');
}
@font-face {
  font-family: 'Cormorant Garamond';
  font-style: normal;
  font-weight: 500;
  font-display: swap;
  src: url(/fonts/basilisk-font-2.ttf) format('truetype');
}
@font-face {
  font-family: 'DM Sans';
  font-style: normal;
  font-weight: 400;
  font-display: swap;
  src: url(/fonts/basilisk-font-3.ttf) format('truetype');
}
@font-face {
  font-family: 'DM Sans';
  font-style: normal;
  font-weight: 500;
  font-display: swap;
  src: url(/fonts/basilisk-font-4.ttf) format('truetype');
}
@font-face {
  font-family: 'DM Sans';
  font-style: normal;
  font-weight: 600;
  font-display: swap;
  src: url(/fonts/basilisk-font-5.ttf) format('truetype');
}
@font-face {
  font-family: 'DM Sans';
  font-style: normal;
  font-weight: 700;
  font-display: swap;
  src: url(/fonts/basilisk-font-6.ttf) format('truetype');
}
@font-face {
  font-family: 'IBM Plex Mono';
  font-style: normal;
  font-weight: 400;
  font-display: swap;
  src: url(/fonts/basilisk-font-7.ttf) format('truetype');
}
@font-face {
  font-family: 'IBM Plex Mono';
  font-style: normal;
  font-weight: 500;
  font-display: swap;
  src: url(/fonts/basilisk-font-8.ttf) format('truetype');
}

:root {
  --bg: #101211;
  --surface: #171a18;
  --surface2: #1d211e;
  --hover: #232923;
  --border: #2b302c;
  --text: #eef1e9;
  --muted: #939b90;
  --faint: #64705f;
  --accent: #d0ed83;
  --accent-text: #182009;
  --amber: #d7b77d;
  --red: #ed9b93;
  --shadow: 0 24px 100px #0009;
  color-scheme: dark;
}
:root[data-theme='light'] {
  --bg: #f5f6f0;
  --surface: #fff;
  --surface2: #f1f3eb;
  --hover: #e9eddf;
  --border: #d9dfd2;
  --text: #20271b;
  --muted: #65715c;
  --faint: #8a9384;
  --accent: #486419;
  --accent-text: #fff;
  --amber: #896018;
  --red: #ad3f38;
  --shadow: 0 24px 100px #26351e30;
  color-scheme: light;
}
* {
  box-sizing: border-box;
}
body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font-family: 'DM Sans', Arial, sans-serif;
  font-size: 14px;
  -webkit-font-smoothing: antialiased;
}
button,
input,
select,
textarea {
  font: inherit;
}
button,
a,
input,
select,
textarea {
  outline-offset: 4px;
}
button,
a {
  -webkit-tap-highlight-color: transparent;
}
button {
  cursor: pointer;
}
button:disabled {
  cursor: not-allowed;
  opacity: 0.45;
}
a {
  color: inherit;
  text-decoration: none;
}
button {
  color: inherit;
  border: 0;
  background: none;
}
h1,
h2,
h3,
h4,
p {
  margin: 0;
}
p {
  line-height: 1.65;
}
small {
  font-size: 11px;
  color: var(--muted);
  line-height: 1.6;
}
input,
select,
textarea {
  width: 100%;
  border: 1px solid var(--border);
  border-radius: 6px;
  background: var(--bg);
  padding: 10px 12px;
  color: var(--text);
  min-width: 0;
}
input:focus,
select:focus,
textarea:focus {
  outline: 1px solid var(--accent);
  border-color: var(--accent);
}
textarea {
  resize: vertical;
  line-height: 1.6;
}
input[type='checkbox'] {
  width: 16px;
  height: 16px;
  accent-color: var(--accent);
  flex-shrink: 0;
}
input::placeholder,
textarea::placeholder {
  color: var(--faint);
}
button:focus-visible,
a:focus-visible {
  outline: 2px solid var(--accent);
}
.shell {
  min-height: 100vh;
}
.rail {
  width: 72px;
  position: fixed;
  inset: 0 auto 0 0;
  border-right: 1px solid var(--border);
  display: flex;
  align-items: center;
  flex-direction: column;
  background: var(--surface);
  z-index: 10;
  padding: 24px 0 16px;
  gap: 18px;
}
.brand-mark {
  color: var(--accent);
  margin: 0 0 36px;
}
.rail-button {
  width: 40px;
  height: 40px;
  border-radius: 7px;
  font-size: 23px;
  color: var(--muted);
}
.rail-button.active,
.rail-button:hover {
  background: var(--hover);
  color: var(--accent);
}
.rail-bottom {
  margin-top: auto;
  display: flex;
  align-items: center;
  gap: 32px;
  flex-direction: column;
}
.vertical {
  writing-mode: vertical-rl;
  font-family: 'IBM Plex Mono', monospace;
  font-size: 9px;
  letter-spacing: 2px;
  color: var(--faint);
}
.workspace {
  margin-left: 72px;
}
.topbar {
  height: 77px;
  border-bottom: 1px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 40px;
  gap: 20px;
}
.wordmark {
  font-weight: 700;
  letter-spacing: 3px;
  font-size: 16px;
}
.wordmark span {
  color: var(--faint);
  margin: 0 10px;
  font-weight: 400;
}
.wordmark small {
  font-family: 'IBM Plex Mono', monospace;
  letter-spacing: 1.7px;
  font-size: 10px;
}
.topbar-right {
  display: flex;
  align-items: center;
  gap: 9px;
  font-family: 'IBM Plex Mono', monospace;
  font-size: 9px;
  letter-spacing: 1px;
  color: var(--muted);
}
.status-dot {
  display: inline-block;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  flex-shrink: 0;
  background: var(--muted);
}
.status-dot.amber {
  background: var(--amber);
}
.status-dot.green {
  background: var(--accent);
}
main {
  max-width: 1720px;
  margin: auto;
  padding: 42px 40px 0;
}
.page-title {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 26px;
}
.eyebrow {
  font-family: 'IBM Plex Mono', monospace;
  color: var(--muted);
  font-size: 10px;
  letter-spacing: 1.5px;
  font-weight: 500;
}
h1 {
  font-size: 40px;
  letter-spacing: -1.7px;
  font-weight: 500;
  margin: 8px 0;
}
.title-dot {
  color: var(--accent);
}
.page-title p {
  color: var(--muted);
  font-size: 13px;
}
.subtle,
.primary,
.button {
  padding: 10px 14px;
  border: 1px solid var(--border);
  border-radius: 6px;
  font-size: 12px;
  line-height: 1.35;
  display: inline-flex;
  gap: 8px;
  align-items: center;
  justify-content: center;
  white-space: nowrap;
}
.subtle {
  background: var(--surface);
}
.subtle:hover {
  background: var(--hover);
}
.primary {
  background: var(--accent);
  border-color: var(--accent);
  color: var(--accent-text);
  font-weight: 600;
}
.primary:hover {
  filter: brightness(1.08);
}
.text-button {
  font-size: 12px;
  color: var(--accent);
  padding: 4px;
}
.source-button {
  color: var(--muted);
  gap: 24px;
}
.mode-note {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 15px;
  border: 1px solid var(--border);
  background: var(--surface);
  border-radius: 6px;
  font-size: 12px;
  line-height: 1.6;
  color: var(--muted);
  margin-bottom: 25px;
}
.mode-tag {
  margin-left: auto;
  font-family: 'IBM Plex Mono', monospace;
  font-size: 9px;
  letter-spacing: 0.5px;
  white-space: nowrap;
  color: var(--faint);
}
.section-label {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  align-items: center;
  margin: 28px 0 16px;
}
.section-label h2,
.section-label h3 {
  font-size: 14px;
  font-weight: 500;
  letter-spacing: -0.2px;
}
.section-label > span {
  font-family: 'IBM Plex Mono', monospace;
  font-size: 9px;
  letter-spacing: 1px;
  color: var(--faint);
}
.top-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 14px;
  margin-bottom: 40px;
}
.prospect-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 19px 20px 0;
  text-align: left;
  transition:
    background 0.16s,
    border-color 0.16s;
  min-width: 0;
  display: flex;
  flex-direction: column;
}
.prospect-card:hover {
  background: var(--surface2);
  border-color: var(--faint);
}
.card-top {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 24px;
}
.card-index {
  font-family: 'IBM Plex Mono', monospace;
  color: var(--faint);
  font-size: 11px;
}
.card-arrow {
  margin-left: auto;
  color: var(--faint);
}
.badge {
  display: inline-flex;
  align-items: center;
  font-size: 10px;
  line-height: 1.4;
  padding: 3px 7px;
  border: 1px solid var(--border);
  border-radius: 4px;
  font-weight: 500;
  white-space: nowrap;
  color: var(--muted);
  background: var(--surface2);
}
.badge.amber {
  color: var(--amber);
  background: color-mix(in srgb, var(--amber) 6%, transparent);
  border-color: color-mix(in srgb, var(--amber) 22%, transparent);
}
.badge.green {
  color: var(--accent);
  background: color-mix(in srgb, var(--accent) 6%, transparent);
  border-color: color-mix(in srgb, var(--accent) 22%, transparent);
}
.badge.red {
  color: var(--red);
  border-color: var(--red);
}
.card-name {
  font-size: 16px;
  font-weight: 550;
  letter-spacing: -0.35px;
}
.card-location {
  color: var(--muted);
  font-size: 11px;
  margin-top: 6px;
}
.prospect-card p {
  font-size: 12px;
  color: var(--muted);
  margin: 17px 0 22px;
  line-height: 1.65;
  flex: 1;
}
.card-bottom {
  display: flex;
  align-items: center;
  gap: 6px;
  border-top: 1px solid var(--border);
  padding: 14px 0;
  color: var(--muted);
  font-size: 9px;
}
.card-bottom strong {
  margin-left: auto;
  color: var(--text);
  font-family: 'IBM Plex Mono', monospace;
  font-size: 15px;
  white-space: nowrap;
}
.card-bottom small {
  font-size: 9px;
  font-weight: 400;
}
.asset-indicator {
  width: 4px;
  height: 4px;
  background: var(--accent);
  border-radius: 1px;
  flex-shrink: 0;
}
.table-section {
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--surface);
  overflow: hidden;
}
.table-toolbar {
  display: flex;
  gap: 20px;
  justify-content: space-between;
  align-items: center;
  padding: 23px 24px;
}
.table-toolbar h2 {
  font-size: 16px;
  font-weight: 500;
}
.table-toolbar h2 span {
  font-family: 'IBM Plex Mono', monospace;
  font-size: 10px;
  margin-left: 8px;
  color: var(--muted);
  background: var(--surface2);
  padding: 3px 6px;
  border: 1px solid var(--border);
  border-radius: 4px;
}
.table-toolbar p {
  color: var(--muted);
  font-size: 11px;
  margin-top: 7px;
}
.actions {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}
.search-row {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 0 24px 18px;
}
.search {
  display: flex;
  align-items: center;
  gap: 8px;
  max-width: 380px;
  flex: 1;
  border: 1px solid var(--border);
  background: var(--bg);
  border-radius: 5px;
  padding-left: 12px;
}
.search > span {
  font-size: 22px;
  color: var(--muted);
}
.search input {
  border: 0;
  background: none;
  padding: 9px 6px;
  font-size: 11px;
}
.search input:focus {
  outline: 0;
}
.search:focus-within {
  outline: 1px solid var(--accent);
}
.table-caption {
  font-family: 'IBM Plex Mono', monospace;
  font-size: 9px;
  margin-left: auto;
  color: var(--faint);
}
.filters {
  display: grid;
  grid-template-columns: repeat(5, 1fr) auto;
  gap: 12px;
  padding: 0 24px 20px;
  align-items: end;
}
.table-scroll {
  overflow: auto;
}
table {
  border-collapse: collapse;
  width: 100%;
  text-align: left;
  min-width: 1080px;
}
thead {
  background: var(--surface2);
}
th {
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
  font-weight: 400;
  color: var(--muted);
  padding: 0 18px;
  font-size: 10px;
}
th:first-child,
td:first-child {
  padding-left: 24px;
}
th button {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  width: 100%;
  font-size: 10px;
  padding: 13px 0;
  white-space: nowrap;
}
th span {
  color: var(--faint);
}
td {
  padding: 22px 18px;
  border-bottom: 1px solid var(--border);
  font-size: 12px;
  vertical-align: top;
  line-height: 1.6;
}
tr:last-child td {
  border-bottom: 0;
}
tbody tr:hover {
  background: color-mix(in srgb, var(--hover) 50%, transparent);
}
td:first-child {
  width: 21%;
}
.facility-link {
  text-align: left;
  padding: 0;
  font-weight: 550;
  white-space: nowrap;
  font-size: 12px;
}
.facility-link span {
  color: var(--faint);
  font-size: 11px;
  padding-left: 7px;
}
.facility-link:hover {
  color: var(--accent);
}
.secondary {
  font-size: 10px;
  color: var(--muted);
  line-height: 1.6;
  margin-top: 5px;
}
.origin-label {
  font-family: 'IBM Plex Mono', monospace;
  font-size: 8px;
  letter-spacing: 0.2px;
  color: var(--faint);
  display: block;
  margin-top: 9px;
}
.load-value {
  font-family: 'IBM Plex Mono', monospace;
  font-size: 11px;
}
.flex-cell {
  max-width: 245px;
  width: 22%;
}
.next-cell {
  width: 23%;
  min-width: 220px;
}
.priority {
  display: flex;
  align-items: center;
  gap: 6px;
  font-family: 'IBM Plex Mono', monospace;
}
.priority strong {
  font-size: 17px;
  font-weight: 500;
  color: var(--accent);
}
.priority > span {
  font-size: 9px;
  color: var(--faint);
}
.next-link {
  display: flex;
  align-items: center;
  gap: 10px;
  text-align: left;
  padding: 0;
  margin-top: 6px;
  color: var(--muted);
  font-size: 10px;
  line-height: 1.6;
}
.next-link span {
  color: var(--accent);
  font-size: 15px;
}
.table-foot {
  border-top: 1px solid var(--border);
  padding: 13px 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 9px;
  color: var(--faint);
  gap: 20px;
}
.table-foot .status-dot {
  width: 4px;
  height: 4px;
  margin-right: 5px;
}
footer {
  padding: 27px 0 25px;
  display: flex;
  gap: 24px;
  align-items: center;
  font-family: 'IBM Plex Mono', monospace;
  font-size: 8px;
  letter-spacing: 0.8px;
  color: var(--faint);
}
footer i {
  font-style: normal;
  margin: 0 7px;
}
footer span:nth-child(2) {
  margin-left: auto;
}
footer a:hover {
  color: var(--accent);
}
.notice {
  display: flex;
  align-items: center;
  justify-content: space-between;
  border: 1px solid var(--amber);
  border-radius: 5px;
  background: var(--surface2);
  color: var(--amber);
  padding: 12px 16px;
  font-size: 12px;
  margin-bottom: 20px;
  line-height: 1.6;
}
.notice button {
  font-size: 22px;
}
.empty {
  padding: 48px;
  text-align: center;
  color: var(--muted);
  font-size: 13px;
  line-height: 1.8;
}
.auth-empty {
  border: 1px solid var(--border);
  border-radius: 10px;
  margin: 40px 0;
  background: var(--surface);
  padding: 80px;
}
.auth-empty h2 {
  color: var(--text);
  font-size: 25px;
}
.auth-empty p {
  margin: 15px 0 25px;
}
.busy {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--surface2);
  border: 1px solid var(--border);
  border-radius: 7px;
  padding: 13px 20px;
  z-index: 50;
  box-shadow: var(--shadow);
  display: flex;
  gap: 12px;
  font-size: 12px;
}
.spinner {
  width: 15px;
  height: 15px;
  border: 2px solid var(--border);
  border-top-color: var(--accent);
  border-radius: 50%;
  animation: spin 0.7s linear infinite;
}
@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}
.modal {
  border: 1px solid var(--border);
  border-radius: 12px;
  background: var(--surface);
  color: var(--text);
  max-width: calc(100vw - 32px);
  width: 520px;
  padding: 0;
  box-shadow: var(--shadow);
  max-height: 90vh;
}
.modal.wide {
  width: 900px;
}
.modal::backdrop {
  background: #050806b8;
  backdrop-filter: blur(5px);
}
.modal-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 23px 28px;
  border-bottom: 1px solid var(--border);
  position: sticky;
  top: 0;
  background: var(--surface);
  z-index: 2;
}
.modal-head h2 {
  font-size: 20px;
  font-weight: 500;
  letter-spacing: -0.5px;
}
.icon-button {
  font-size: 25px;
  color: var(--muted);
  width: 30px;
  height: 30px;
}
.modal-body {
  padding: 24px 28px 30px;
}
.stack {
  display: flex;
  flex-direction: column;
  gap: 17px;
}
.stack > p {
  font-size: 13px;
  color: var(--muted);
}
.field {
  display: flex;
  flex-direction: column;
  gap: 8px;
  min-width: 0;
}
.field > span {
  font-size: 11px;
  color: var(--muted);
}
.form-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 17px;
}
.inline {
  display: flex;
  gap: 9px;
  align-items: center;
  flex-wrap: wrap;
}
.inline .field {
  flex: 1;
}
.inline > .primary {
  align-self: flex-end;
}
.error {
  color: var(--red);
  font-size: 12px;
  line-height: 1.7;
  padding: 12px;
  border: 1px solid var(--red);
  border-radius: 5px;
}
.sticky-error {
  position: sticky;
  bottom: 0;
  background: var(--surface2);
  margin-top: 20px;
}
.tabs {
  display: flex;
  gap: 25px;
  border-bottom: 1px solid var(--border);
}
.tabs button {
  padding: 12px 0;
  font-size: 12px;
  color: var(--muted);
  border-bottom: 2px solid transparent;
}
.tabs button.active {
  border-color: var(--accent);
  color: var(--text);
}
.import-templates {
  display: flex;
  gap: 20px;
  font-size: 11px;
  color: var(--accent);
}
.dropzone {
  padding: 25px;
  border: 1px dashed var(--faint);
  border-radius: 7px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  background: var(--bg);
}
.dropzone > span {
  font-size: 25px;
  color: var(--accent);
}
.dropzone strong {
  font-size: 13px;
  font-weight: 500;
}
.dropzone input {
  max-width: 300px;
  margin-top: 8px;
  font-size: 11px;
}
.code-input {
  font-family: 'IBM Plex Mono', monospace;
  font-size: 11px;
  line-height: 1.7;
}
.import-preview {
  border: 1px solid var(--border);
  padding: 0 20px 20px;
  border-radius: 7px;
  background: var(--bg);
}
.preview-row {
  display: flex;
  flex-direction: column;
  gap: 5px;
  padding: 15px 0;
  border-top: 1px solid var(--border);
  font-size: 12px;
}
.preview-row > span {
  color: var(--muted);
  font-size: 11px;
}
.source-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 15px;
}
.source-grid > div {
  padding: 20px;
  border: 1px solid var(--border);
  border-radius: 7px;
  background: var(--bg);
}
.source-grid h3 {
  font-size: 15px;
  font-weight: 500;
  margin: 13px 0 8px;
}
.source-grid p {
  font-size: 12px;
  color: var(--muted);
}
.job {
  border-top: 1px solid var(--border);
  padding: 20px 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
}
.job strong {
  font-size: 13px;
}
.job p {
  font-size: 12px;
  color: var(--muted);
  margin: 9px 0;
  overflow-wrap: anywhere;
}
.fineprint {
  font-size: 11px;
  color: var(--muted);
  line-height: 1.7;
  margin: 12px 0;
}
.detail-subhead {
  display: flex;
  justify-content: space-between;
  gap: 15px;
  align-items: center;
  font-size: 11px;
  color: var(--muted);
}
.detail-intro {
  padding: 28px 0;
}
.detail-intro p {
  font-size: 17px;
  line-height: 1.65;
  margin: 12px 0;
  letter-spacing: -0.2px;
}
.vector-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1px;
  background: var(--border);
  border: 1px solid var(--border);
  border-radius: 7px;
  overflow: hidden;
}
.vector-grid > div {
  background: var(--bg);
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.vector-grid > div > span {
  font-family: 'IBM Plex Mono', monospace;
  font-size: 9px;
  color: var(--muted);
  letter-spacing: 0.5px;
}
.vector-grid strong {
  font-size: 13px;
  font-weight: 500;
  line-height: 1.6;
}
.next-box {
  display: flex;
  gap: 25px;
  justify-content: space-between;
  padding: 22px;
  background: color-mix(in srgb, var(--accent) 5%, var(--bg));
  border: 1px solid color-mix(in srgb, var(--accent) 25%, var(--border));
  border-radius: 7px;
  margin-top: 22px;
}
.next-box h3 {
  font-size: 16px;
  font-weight: 500;
  margin: 10px 0;
}
.next-box p {
  font-size: 12px;
  color: var(--muted);
  margin-bottom: 8px;
}
.next-box > span {
  font-size: 25px;
  color: var(--accent);
}
.capacity-line {
  display: flex;
  gap: 20px;
  justify-content: space-between;
  padding: 20px 0;
  font-size: 11px;
  color: var(--muted);
  line-height: 1.6;
}
.capacity-line strong {
  font-weight: 500;
  color: var(--text);
}
.disclosure {
  border-top: 1px solid var(--border);
  padding: 17px 0;
  font-size: 12px;
}
.disclosure summary {
  cursor: pointer;
  color: var(--muted);
  font-size: 12px;
}
.disclosure[open] summary {
  color: var(--text);
  margin-bottom: 18px;
}
.disclosure > p {
  font-size: 12px;
  color: var(--muted);
}
.detail-section {
  margin: 15px 0 28px;
}
.detail-section > h3 {
  font-size: 16px;
  font-weight: 500;
  margin-bottom: 16px;
}
.asset-row {
  padding: 17px;
  border: 1px solid var(--border);
  border-radius: 7px;
  background: var(--bg);
  margin-bottom: 12px;
}
.asset-row > strong {
  font-size: 13px;
  font-weight: 500;
  display: block;
  margin-bottom: 12px;
}
.asset-row p {
  font-size: 12px;
  color: var(--muted);
  margin: 12px 0 7px;
}
.evidence {
  padding: 21px 0;
  border-top: 1px solid var(--border);
}
.evidence h4 {
  font-size: 13px;
  font-weight: 500;
  margin: 12px 0 5px;
}
.evidence p {
  font-size: 13px;
  margin-bottom: 10px;
}
.evidence > a {
  font-size: 12px;
  color: var(--accent);
}
blockquote {
  margin: 15px 0;
  border-left: 2px solid var(--border);
  padding: 0 15px;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.8;
}
.review-actions {
  display: flex;
  gap: 7px;
  margin-top: 12px;
  flex-wrap: wrap;
}
.review-actions button {
  font-size: 10px;
  padding: 7px 10px;
}
.detail-section > .field {
  margin: 20px 0;
}
.checklist {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 14px;
}
.checklist label,
.authorization {
  display: flex;
  gap: 10px;
  align-items: flex-start;
  line-height: 1.7;
  font-size: 12px;
  color: var(--muted);
}
.document {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 10px;
  padding: 16px;
  border: 1px solid var(--border);
  background: var(--bg);
  border-radius: 6px;
  margin: 10px 0;
  font-size: 12px;
}
.document small {
  display: block;
  margin-top: 4px;
}
.selected {
  color: var(--accent);
  border-color: var(--faint);
}
@media (min-width: 1600px) {
  .prospect-card {
    padding: 22px 24px 0;
  }
  .prospect-card p {
    font-size: 13px;
  }
  .card-name {
    font-size: 18px;
  }
  .card-bottom {
    font-size: 10px;
  }
  td {
    padding-top: 25px;
    padding-bottom: 25px;
  }
}
@media (max-width: 1250px) {
  main {
    padding: 30px 25px 0;
  }
  .topbar {
    padding: 0 25px;
  }
  .table-toolbar {
    align-items: flex-start;
    flex-direction: column;
  }
  .top-grid {
    gap: 10px;
  }
  .prospect-card {
    padding: 16px 15px 0;
  }
  .card-top {
    gap: 6px;
  }
  .card-top .badge {
    font-size: 8px;
  }
  .card-name {
    font-size: 14px;
  }
  .card-bottom {
    flex-wrap: wrap;
  }
  .mode-tag {
    display: none;
  }
  .filters {
    grid-template-columns: repeat(3, 1fr);
  }
}
@media (max-width: 900px) {
  .top-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .topbar-right {
    font-size: 8px;
  }
  .wordmark small {
    display: none;
  }
  .card-name {
    font-size: 17px;
  }
  .card-bottom {
    flex-wrap: nowrap;
  }
  .section-label > span {
    font-size: 8px;
  }
  .rail {
    width: 55px;
  }
  .workspace {
    margin-left: 55px;
  }
  .rail-button {
    width: 34px;
    height: 34px;
  }
  .topbar {
    height: 65px;
  }
  h1 {
    font-size: 35px;
  }
  .filters {
    grid-template-columns: repeat(2, 1fr);
  }
  .table-foot > span:last-child {
    display: none;
  }
  .card-top {
    margin-bottom: 18px;
  }
  .source-button {
    font-size: 10px;
    gap: 10px;
  }
  .modal-body {
    padding: 22px;
  }
  .modal-head {
    padding: 20px 22px;
  }
}
@media (max-width: 600px) {
  main {
    padding: 25px 16px 0;
  }
  .topbar {
    padding: 0 16px;
  }
  .wordmark {
    font-size: 12px;
    letter-spacing: 2px;
  }
  .wordmark span {
    display: none;
  }
  .topbar-right {
    font-size: 7px;
    letter-spacing: 0.2px;
  }
  .top-grid {
    grid-template-columns: 1fr;
  }
  .prospect-card {
    padding: 18px 20px 0;
  }
  .prospect-card p {
    margin: 12px 0 15px;
  }
  .card-top {
    margin-bottom: 17px;
  }
  .card-top .badge {
    font-size: 9px;
  }
  .top-grid {
    margin-bottom: 28px;
  }
  .section-label {
    align-items: flex-start;
  }
  .section-label > span {
    max-width: 145px;
    text-align: right;
    line-height: 1.8;
  }
  .mode-note {
    font-size: 10px;
  }
  .page-title {
    align-items: flex-start;
    gap: 10px;
  }
  .page-title p {
    font-size: 11px;
  }
  .source-button {
    padding: 8px;
    font-size: 9px;
  }
  .table-toolbar {
    padding: 20px 16px;
  }
  .actions {
    gap: 7px;
  }
  .actions > * {
    font-size: 10px;
    padding: 9px 11px;
  }
  .search-row {
    padding: 0 16px 15px;
  }
  .search input {
    font-size: 10px;
  }
  .table-caption {
    display: none;
  }
  .filters {
    padding: 0 16px 16px;
  }
  .table-foot {
    padding: 12px 16px;
    line-height: 1.8;
    font-size: 8px;
  }
  footer {
    font-size: 7px;
    flex-wrap: wrap;
    gap: 15px;
  }
  footer span:nth-child(2) {
    display: none;
  }
  .modal {
    max-width: calc(100vw - 14px);
    max-height: 95vh;
  }
  .modal-body {
    padding: 18px;
  }
  .modal-head {
    padding: 17px 18px;
  }
  .modal-head h2 {
    font-size: 18px;
  }
  .form-grid,
  .source-grid,
  .checklist,
  .vector-grid {
    grid-template-columns: 1fr;
  }
  .detail-subhead {
    flex-direction: column;
    align-items: flex-start;
  }
  .detail-intro p {
    font-size: 15px;
  }
  .capacity-line {
    flex-direction: column;
    gap: 5px;
  }
  .job {
    align-items: flex-start;
    flex-direction: column;
  }
  .auth-empty {
    padding: 40px 20px;
  }
  .auth-empty h2 {
    font-size: 20px;
  }
  .busy {
    max-width: 90vw;
    white-space: nowrap;
  }
  .table-scroll {
    scrollbar-width: thin;
  }
  .rail {
    width: 45px;
  }
  .workspace {
    margin-left: 45px;
  }
  .brand-mark {
    transform: scale(0.8);
  }
  .vertical {
    font-size: 8px;
  }
}
@media (prefers-reduced-motion: reduce) {
  * {
    animation: none !important;
    transition: none !important;
  }
}
.acquisition-card {
  cursor: default;
  padding-bottom: 0;
}
.card-title-button {
  padding: 0;
  text-align: left;
  display: flex;
  align-items: flex-start;
  gap: 9px;
  justify-content: space-between;
  line-height: 1.5;
  width: 100%;
}
.card-title-button:hover {
  color: var(--accent);
}
.acquisition-card .card-top {
  margin-bottom: 17px;
}
.acquisition-price {
  font-family: 'IBM Plex Mono', monospace;
  font-size: 23px;
  letter-spacing: -0.8px;
  margin: 19px 0 17px;
}
.acquisition-price small {
  display: block;
  font-family: 'DM Sans', Arial, sans-serif;
  font-size: 10px;
  letter-spacing: 0;
  margin-top: 5px;
}
.acquisition-facts {
  display: grid;
  gap: 13px;
  padding: 15px 0;
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
}
.acquisition-facts > div {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  font-size: 11px;
  line-height: 1.5;
}
.acquisition-facts > div > span {
  color: var(--muted);
  font-size: 10px;
}
.acquisition-facts strong {
  font-weight: 500;
  text-align: right;
  max-width: 60%;
}
.acquisition-card p {
  margin: 16px 0;
  font-size: 12px;
  line-height: 1.6;
}
.acquisition-links {
  border-top: 1px solid var(--border);
  padding: 13px 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 7px;
  font-size: 10px;
}
.acquisition-links a {
  color: var(--muted);
}
.acquisition-links a:hover {
  color: var(--accent);
}
.acquisition-links .text-button {
  font-size: 10px;
  padding: 0;
}
.acquisition-detail {
  padding: 0 0 23px;
}
.acquisition-detail > .acquisition-facts {
  grid-template-columns: 1fr 1fr;
  gap: 16px 28px;
  margin-bottom: 15px;
}
.acquisition-detail > p {
  font-size: 12px;
  color: var(--muted);
  margin: 13px 0;
}
.acquisition-detail .disclosure .field {
  margin-top: 14px;
}
.filters {
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
}
@media (max-width: 600px) {
  .acquisition-detail > .acquisition-facts {
    grid-template-columns: 1fr;
  }
  .acquisition-price {
    font-size: 25px;
  }
  .filters {
    grid-template-columns: 1fr 1fr;
  }
  .acquisition-card .card-name {
    font-size: 17px;
  }
}

/* Focused acquisition shortlist. Advanced origination tools remain deferred. */
.candidate-workspace {
  max-width: 1280px;
  margin: auto;
  padding: 0 48px 32px;
}
.quiet-header {
  min-height: 94px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1px solid var(--border);
  gap: 20px;
  color: var(--muted);
  font-size: 12px;
}
.quiet-brand {
  text-decoration: none;
  color: var(--text);
  letter-spacing: 0.2em;
  font-weight: 700;
}
.quiet-brand span {
  color: var(--faint);
  font-size: 10px;
  margin-left: 20px;
}
.quiet-intro {
  padding: 65px 0 45px;
}
.quiet-intro .eyebrow {
  font:
    11px 'IBM Plex Mono',
    monospace;
  letter-spacing: 0.16em;
  color: var(--accent);
}
.quiet-intro h1 {
  font-size: clamp(36px, 5vw, 60px);
  line-height: 1.08;
  font-weight: 450;
  letter-spacing: -0.05em;
  margin: 20px 0;
}
.quiet-intro h1 span {
  color: var(--muted);
}
.quiet-intro > p:last-child {
  color: var(--muted);
  font-size: 16px;
  line-height: 1.6;
}
.quiet-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 20px;
}
.quiet-card {
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 28px;
  background: var(--surface);
}
.quiet-card-meta {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 8px;
  color: var(--muted);
  font-size: 11px;
}
.quiet-warning {
  color: var(--amber);
}
.quiet-card h2 {
  margin: 25px 0 7px;
  font-size: 25px;
  font-weight: 500;
  letter-spacing: -0.03em;
}
.quiet-card h2 button {
  color: inherit;
  font: inherit;
  text-align: left;
  border: 0;
  padding: 0;
  background: none;
}
.quiet-card h2 button:hover {
  color: var(--accent);
}
.quiet-type {
  color: var(--muted);
  font-size: 12px;
  margin: 0;
  line-height: 1.5;
}
.quiet-price {
  font-size: 27px;
  letter-spacing: -0.03em;
  margin: 26px 0 20px;
}
.quiet-price span {
  display: block;
  color: var(--muted);
  font-size: 11px;
  letter-spacing: 0;
  margin-top: 5px;
}
.quiet-thesis {
  color: var(--muted);
  line-height: 1.65;
  min-height: 70px;
}
.quiet-actions {
  display: flex;
  gap: 24px;
  border-top: 1px solid var(--border);
  padding-top: 18px;
  margin-top: 24px;
}
.quiet-actions button {
  display: flex;
  gap: 18px;
  align-items: center;
  background: none;
  border: 0;
  padding: 2px 0;
  color: var(--text);
  font-size: 13px;
}
.quiet-actions button span {
  color: var(--accent);
}
.quiet-actions button:hover {
  color: var(--accent);
}
.quiet-footer {
  font-size: 11px;
  color: var(--muted);
  line-height: 1.6;
  margin-top: 30px;
}
.dossier-tabs {
  display: flex;
  gap: 24px;
  border-bottom: 1px solid var(--border);
  margin-bottom: 26px;
}
.dossier-tabs button {
  background: none;
  border: 0;
  border-bottom: 2px solid transparent;
  color: var(--muted);
  padding: 8px 0 14px;
}
.dossier-tabs button[aria-selected='true'] {
  color: var(--accent);
  border-bottom-color: var(--accent);
}
.dossier-content {
  max-width: 840px;
  line-height: 1.7;
}
.dossier-content h3 {
  font-size: 16px;
  margin: 30px 0 12px;
}
.dossier-content p,
.dossier-content li {
  color: var(--muted);
}
.dossier-content li {
  margin-bottom: 10px;
  padding-left: 4px;
}
.dossier-content .dossier-lead {
  font-size: 19px;
  color: var(--text);
  line-height: 1.6;
}
.dossier-facts {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 18px;
  border-block: 1px solid var(--border);
  padding: 22px 0;
  margin: 26px 0;
}
.dossier-facts dt {
  color: var(--muted);
  font-size: 12px;
}
.dossier-facts dd {
  margin: 4px 0 0;
}
.dossier-callout,
.offer-verdict {
  background: var(--surface2);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 20px;
  margin: 24px 0;
}
.dossier-callout p:last-child {
  margin-bottom: 0;
}
.offer-verdict > span {
  color: var(--amber);
  font-size: 12px;
}
.offer-verdict h3 {
  margin: 8px 0;
  font-size: 22px;
}
.dossier-content details {
  border-bottom: 1px solid var(--border);
  padding: 16px 0;
}
.dossier-content summary {
  cursor: pointer;
}
.dossier-content .dossier-small {
  font-size: 12px;
}
.dossier-source {
  display: inline-block;
  margin: 15px 0;
  color: var(--accent);
}
.scenario-mode {
  display: grid;
  gap: 8px;
  font-size: 12px;
}
.scenario-mode select {
  width: 100%;
}
.underwriting-inputs {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 18px;
  margin: 22px 0;
}
.underwriting-inputs label {
  display: grid;
  gap: 7px;
  color: var(--muted);
  font-size: 12px;
}
.underwriting-inputs input {
  width: 100%;
  min-width: 0;
}
.underwriting-checks {
  display: grid;
  gap: 15px;
}
.underwriting-checks label {
  display: flex;
  gap: 12px;
  align-items: flex-start;
  color: var(--muted);
  font-size: 13px;
}
.underwriting-checks input {
  flex: 0 0 auto;
  width: 16px;
  height: 16px;
  margin-top: 4px;
}
.scenario-table {
  width: 100%;
  font-size: 12px;
  border-collapse: collapse;
}
.scenario-table th,
.scenario-table td {
  padding: 10px 6px;
  border-bottom: 1px solid var(--border);
  text-align: left;
}
@media (max-width: 680px) {
  .candidate-workspace {
    padding: 0 20px 25px;
  }
  .quiet-header {
    min-height: 75px;
  }
  .quiet-header > span,
  .quiet-brand span {
    display: none;
  }
  .quiet-intro {
    padding: 35px 0 25px;
  }
  .quiet-grid {
    grid-template-columns: 1fr;
    gap: 14px;
  }
  .quiet-card {
    padding: 22px;
  }
  .quiet-card h2 {
    font-size: 23px;
  }
  .quiet-thesis {
    min-height: 0;
  }
  .dossier-facts,
  .underwriting-inputs {
    grid-template-columns: 1fr;
  }
}
.quiet-intro {
  padding: 34px 0 25px;
}
.quiet-intro h1 {
  font-size: clamp(32px, 4vw, 46px);
  margin: 15px 0;
}
.quiet-card {
  padding: 24px;
}
.quiet-card h2 {
  margin-top: 18px;
}
.quiet-price {
  margin: 20px 0 16px;
}
.quiet-thesis {
  min-height: 48px;
  margin-bottom: 14px;
}
.quiet-actions {
  margin-top: 18px;
  padding-top: 15px;
}
.card-offer-pair {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 18px;
  margin: 26px 0;
}
.card-offer-pair span {
  display: block;
  color: var(--muted);
  font-size: 11px;
  margin-bottom: 7px;
}
.card-offer-pair strong {
  font-size: 25px;
  font-weight: 450;
  letter-spacing: -0.03em;
}
.card-offer-pair > div:last-child strong {
  color: var(--accent);
}
.offer-result {
  margin: 12px 0 24px;
}
.offer-result > span {
  color: var(--muted);
  font-size: 12px;
}
.offer-result > strong {
  display: block;
  font-size: 56px;
  line-height: 1.2;
  letter-spacing: -0.04em;
  color: var(--accent);
  font-weight: 450;
  margin: 10px 0;
}
.offer-result > p {
  margin: 0;
  font-size: 12px;
}
.reset-offer {
  float: right;
  font-size: 12px;
}
.source-note {
  padding: 14px 0;
}
@media (max-width: 420px) {
  .card-offer-pair strong {
    font-size: 22px;
  }
  .offer-result > strong {
    font-size: 44px;
  }
}
.shortlist-sort {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin: 0 0 20px;
  color: var(--muted);
  font-size: 11px;
}
.shortlist-sort label {
  display: flex;
  gap: 10px;
  align-items: center;
}
.shortlist-sort select {
  width: auto;
  padding: 8px 10px;
  font-size: 12px;
}
.power-signal {
  color: var(--accent) !important;
  font-size: 12px;
  margin: 16px 0 0;
}
.card-dr-metrics {
  display: grid;
  grid-template-columns: 1fr 1.3fr 0.8fr;
  gap: 14px;
  margin: 20px 0 8px;
  padding-top: 18px;
  border-top: 1px solid var(--border);
}
.card-dr-metrics dt {
  color: var(--muted);
  font-size: 10px;
}
.card-dr-metrics dd {
  margin: 6px 0 0;
  font-size: 18px;
}
.card-scenario-note {
  font-size: 10px;
  color: var(--muted);
  margin: 12px 0;
}
.demand-model {
  border-block: 1px solid var(--border);
  padding: 8px 0 18px;
  margin-bottom: 24px;
}
.demand-title {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}
.demand-title > span {
  font-size: 11px;
  color: var(--amber);
}
.earnings-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px 18px;
  margin: 20px 0;
}
.earnings-grid dt {
  color: var(--muted);
  font-size: 11px;
}
.earnings-grid dd {
  margin: 7px 0 0;
  font-size: 24px;
  color: var(--accent);
  letter-spacing: -0.025em;
}
@media (max-width: 680px) {
  .shortlist-sort {
    align-items: flex-start;
    flex-direction: column;
  }
  .earnings-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .earnings-grid dd {
    font-size: 21px;
  }
  .demand-title {
    align-items: baseline;
  }
  .card-dr-metrics dd {
    font-size: 16px;
  }
}

:root[data-theme='dark'] {
  --bg: #0a100d;
  --surface: #101a14;
  --surface2: #15231a;
  --border: #293a2d;
  --text: #f0f1e7;
  --muted: #9baa9c;
  --faint: #6c806e;
  --accent: #d3ef8a;
  --amber: #cfb989;
  --shadow: 0 32px 120px #000b;
}
body {
  background:
    radial-gradient(ellipse at 90% 0%, #263c2229, transparent 45%),
    radial-gradient(ellipse at 0% 60%, #19342320, transparent 55%), var(--bg);
}
.candidate-workspace {
  max-width: 1400px;
  padding: 0 56px 36px;
  position: relative;
}
.quiet-header {
  min-height: 130px;
  border-bottom: 1px solid #50614755;
  position: relative;
}
.quiet-header::after {
  content: '';
  width: 48px;
  height: 3px;
  background: var(--accent);
  position: absolute;
  left: 0;
  bottom: -2px;
}
.quiet-brand {
  display: flex;
  flex-direction: column;
  gap: 9px;
  letter-spacing: 0.3em;
}
.quiet-brand strong {
  font-size: 23px;
  font-weight: 600;
}
.quiet-brand > span {
  margin: 0;
  font:
    9px 'IBM Plex Mono',
    monospace;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--muted);
}
.header-signature {
  display: flex;
  align-items: center;
  gap: 24px;
}
.header-signature > span:first-child {
  text-align: right;
  font:
    10px 'IBM Plex Mono',
    monospace;
  letter-spacing: 0.15em;
  color: var(--accent);
}
.header-signature small {
  display: block;
  color: var(--faint);
  font-size: 9px;
  letter-spacing: 0.1em;
  margin-top: 9px;
}
/* The standalone SVG frames only the main mark, independently of stylesheet loading. */
.basilisk-emblem {
  display: block;
  width: 86px;
  height: 86px;
  position: relative;
  overflow: hidden;
  flex-shrink: 0;
  mix-blend-mode: lighten;
  filter: drop-shadow(0 0 13px #d3ef8a12);
}
.basilisk-emblem img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: contain;
}
.quiet-intro {
  padding: 46px 0 34px;
  position: relative;
  overflow: hidden;
}
.quiet-intro::before {
  content: '';
  position: absolute;
  inset: 0;
  z-index: -1;
  background-image:
    linear-gradient(#a8c78706 1px, transparent 1px),
    linear-gradient(90deg, #a8c78706 1px, transparent 1px);
  background-size: 40px 40px;
  mask-image: linear-gradient(90deg, transparent 25%, #000 100%);
}
.quiet-intro .eyebrow {
  font:
    9px 'IBM Plex Mono',
    monospace;
  letter-spacing: 0.17em;
  color: var(--muted);
  display: flex;
  align-items: center;
  gap: 10px;
  margin: 0 0 18px;
}
.eyebrow > span {
  width: 5px;
  height: 5px;
  background: var(--accent);
  box-shadow: 0 0 12px #d3ef8a50;
  transform: rotate(45deg);
}
.quiet-intro h1 {
  font-family: 'Cormorant Garamond', Georgia, serif;
  font-size: clamp(42px, 5.2vw, 72px);
  font-weight: 400;
  letter-spacing: -0.035em;
  margin: 0;
  line-height: 1.08;
}
.quiet-intro h1 em {
  font-weight: 400;
  color: #b5c4aa;
}
.quiet-intro h1 > span {
  color: var(--accent);
}
.folio-count {
  position: absolute;
  right: 10px;
  bottom: 25px;
  font:
    500 94px/0.8 'Cormorant Garamond',
    Georgia,
    serif;
  color: #a7c38819;
  letter-spacing: -0.06em;
}
.folio-count > span {
  display: block;
  font:
    8px 'IBM Plex Mono',
    monospace;
  color: var(--faint);
  letter-spacing: 0.16em;
  margin-top: 13px;
  padding-left: 7px;
}
.shortlist-sort {
  padding: 13px 0;
  border-top: 1px solid #2e403038;
  margin-bottom: 22px;
  font-family: 'IBM Plex Mono', monospace;
  font-size: 9px;
  letter-spacing: 0.025em;
}
.shortlist-sort select {
  border-radius: 2px;
  background: #152019;
  border-color: #36492f;
  padding: 9px 28px 9px 12px;
  font:
    10px 'IBM Plex Mono',
    monospace;
  color: var(--text);
}
.quiet-grid {
  gap: 22px;
}
.quiet-card {
  padding: 27px 28px 20px;
  border: 1px solid #344631;
  border-radius: 3px;
  position: relative;
  isolation: isolate;
  background:
    linear-gradient(125deg, #1b2a1d88, transparent 48%), linear-gradient(160deg, #142019, #0e1712);
  box-shadow:
    0 6px 22px #0002,
    inset 0 1px #ffffff05;
  transition:
    transform 180ms ease,
    border-color 180ms ease,
    box-shadow 180ms ease;
}
.quiet-card::before {
  content: '';
  position: absolute;
  top: -1px;
  left: 24px;
  height: 1px;
  width: 65px;
  background: #d3ef8aa6;
}
.quiet-card::after {
  content: attr(data-index);
  position: absolute;
  z-index: -1;
  right: 18px;
  top: 41px;
  font:
    400 86px/1 'Cormorant Garamond',
    Georgia,
    serif;
  color: #c7e5930a;
  letter-spacing: -0.06em;
  pointer-events: none;
}
.quiet-card:hover {
  transform: translateY(-3px);
  border-color: #7a9453;
  box-shadow:
    0 16px 36px #0004,
    inset 0 1px #d3ef8a12;
}
.quiet-card-meta {
  font:
    9px 'IBM Plex Mono',
    monospace;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: #9bad98;
}
.quiet-card-meta > span:last-child {
  color: #a8b99c;
  font-size: 9px;
}
.quiet-card-meta > span:last-child::before {
  content: '';
  width: 4px;
  height: 4px;
  border-radius: 50%;
  display: inline-block;
  margin-right: 6px;
  background: #accc7c;
  vertical-align: 2px;
}
.quiet-card h2 {
  font-family: 'Cormorant Garamond', Georgia, serif;
  font-size: 30px;
  font-weight: 500;
  line-height: 1.16;
  letter-spacing: -0.015em;
  margin: 24px 0 8px;
  padding-right: 25px;
}
.quiet-card h2 button {
  transition: color 150ms ease;
}
.quiet-type {
  font-size: 11px;
  line-height: 1.55;
  color: #8d9d8c;
}
.power-signal {
  font:
    10px 'IBM Plex Mono',
    monospace;
  line-height: 1.6;
  letter-spacing: -0.01em;
  margin-top: 17px;
  color: #bdceaa !important;
}
.card-offer-pair {
  margin: 23px 0 20px;
  gap: 18px;
}
.card-offer-pair span {
  text-transform: uppercase;
  font:
    8px 'IBM Plex Mono',
    monospace;
  letter-spacing: 0.08em;
  color: #82967e;
  margin-bottom: 8px;
}
.card-offer-pair strong {
  font-size: 26px;
  font-weight: 450;
  letter-spacing: -0.045em;
  font-variant-numeric: tabular-nums;
}
.card-offer-pair > div:first-child strong {
  color: #dee6d8;
}
.card-offer-pair > div:last-child strong {
  color: var(--accent);
}
.card-dr-metrics {
  border-top: 1px solid #34463180;
  margin-top: 20px;
  padding: 16px 0 0;
}
.card-dr-metrics dt {
  font:
    8px 'IBM Plex Mono',
    monospace;
  text-transform: uppercase;
  letter-spacing: 0.045em;
  color: #8da184;
  line-height: 1.5;
}
.card-dr-metrics dd {
  font:
    500 17px 'IBM Plex Mono',
    monospace;
  letter-spacing: -0.055em;
  color: #e7eddf;
  margin-top: 8px;
}
.card-dr-metrics > div:last-child dd {
  color: var(--accent);
}
.card-scenario-note {
  font-size: 9px;
  color: #9aaa94;
  margin: 16px 0 12px;
  line-height: 1.5;
}
.quiet-actions {
  gap: 28px;
  border-top: 1px solid #34463180;
  padding-top: 15px;
}
.quiet-actions button {
  font-size: 11px;
  color: #dee7d6;
  gap: 16px;
}
.quiet-actions button:last-child {
  margin-left: auto;
}
.quiet-actions button span {
  font-size: 16px;
  transition: transform 150ms ease;
}
.quiet-actions button:hover span {
  transform: translate(2px, -1px);
}
.quiet-footer {
  border-top: 1px solid #344631;
  padding-top: 20px;
  margin-top: 30px;
  color: #9aaa94;
  font:
    9px/1.8 'IBM Plex Mono',
    monospace;
  letter-spacing: 0.02em;
}
.candidate-workspace .modal {
  border-radius: 5px;
  border: 1px solid #63784a;
  background: linear-gradient(135deg, #19281c, #0d1711 70%);
  box-shadow:
    0 40px 150px #000d,
    0 0 0 5px #17221855;
}
.candidate-workspace .modal::backdrop {
  background: #050b08d9;
  backdrop-filter: blur(9px);
}
.candidate-workspace .modal-head {
  background: #101c14f5;
  border-bottom: 1px solid #3d5135;
  padding: 22px 28px;
}
.candidate-workspace .modal-head h2 {
  font-family: 'Cormorant Garamond', Georgia, serif;
  font-size: 30px;
  font-weight: 500;
  line-height: 1.15;
  letter-spacing: -0.02em;
  margin: 0;
}
.candidate-workspace .icon-button {
  background: #20311e;
  border: 1px solid #415239;
  border-radius: 50%;
  color: var(--accent);
  line-height: 1;
  flex-shrink: 0;
}
.dossier-tabs {
  gap: 30px;
  border-bottom-color: #3c5034;
}
.dossier-tabs button {
  font:
    10px 'IBM Plex Mono',
    monospace;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  padding: 8px 0 16px;
}
.dossier-content h3 {
  font-size: 14px;
  font-weight: 500;
  color: #e8eddf;
}
.dossier-content .dossier-lead {
  font-family: 'Cormorant Garamond', Georgia, serif;
  font-size: 25px;
  line-height: 1.4;
  color: #e0e7d7;
}
.dossier-facts {
  border-color: #32472d;
}
.dossier-facts dt {
  font:
    9px/1.5 'IBM Plex Mono',
    monospace;
  text-transform: uppercase;
  color: #91a687;
}
.dossier-facts dd {
  margin-top: 7px;
  font-size: 13px;
  line-height: 1.6;
}
.offer-result {
  position: relative;
  overflow: hidden;
  padding: 24px;
  border: 1px solid #566d3f;
  border-radius: 3px;
  background:
    radial-gradient(ellipse at 90% 0%, #739b3a28, transparent 70%),
    linear-gradient(120deg, #22351c88, #101b12);
}
.offer-result::after {
  content: '↗';
  position: absolute;
  right: 24px;
  top: 22px;
  font-size: 40px;
  color: #b9dc7622;
}
.offer-result > span {
  color: #b7c7a7;
  font:
    9px 'IBM Plex Mono',
    monospace;
  text-transform: uppercase;
  letter-spacing: 0.1em;
}
.offer-result > strong {
  font-family: 'Cormorant Garamond', Georgia, serif;
  font-size: 68px;
  font-weight: 500;
  letter-spacing: -0.04em;
  margin: 13px 0;
  line-height: 1;
}
.offer-result > p {
  font-size: 11px;
  color: #adbea1;
}
.demand-model {
  border-color: #3c5034;
}
.demand-title > span {
  font:
    8px 'IBM Plex Mono',
    monospace;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}
.earnings-grid {
  gap: 1px;
  border: 1px solid #354c2f;
  background: #354c2f;
  border-radius: 3px;
  overflow: hidden;
}
.earnings-grid > div {
  padding: 18px 16px;
  background: linear-gradient(135deg, #1d2b1c, #142016);
}
.earnings-grid dt {
  font:
    8px/1.6 'IBM Plex Mono',
    monospace;
  text-transform: uppercase;
  color: #a6b99b;
  letter-spacing: 0.02em;
}
.earnings-grid dd {
  font:
    500 24px 'Cormorant Garamond',
    Georgia,
    serif;
  margin-top: 8px;
  letter-spacing: -0.02em;
}
.earnings-grid > div:nth-child(2),
.earnings-grid > div:nth-child(4),
.earnings-grid > div:nth-child(6) {
  background: linear-gradient(135deg, #273b20, #1b2a19);
}
.underwriting-inputs {
  gap: 18px 22px;
}
.underwriting-inputs label {
  font:
    9px/1.7 'IBM Plex Mono',
    monospace;
  color: #a8b99d;
}
.underwriting-inputs input {
  border-radius: 2px;
  background: #0c150f;
  border: 1px solid #3a5032;
  font:
    12px 'IBM Plex Mono',
    monospace;
  color: #e7eddf;
  padding: 12px;
  box-shadow: inset 0 2px 5px #0002;
}
.underwriting-inputs input:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px #d3ef8a0b;
}
.dossier-content details {
  border-color: #354a2e;
}
.dossier-content summary {
  font-size: 12px;
  color: #cfddc2;
}
.scenario-table {
  font:
    10px/1.6 'IBM Plex Mono',
    monospace;
}
.scenario-table th {
  color: #bcd1a7;
  font-weight: 400;
}
.scenario-table th,
.scenario-table td {
  border-color: #334b2b;
  white-space: normal;
  overflow-wrap: anywhere;
}
.reset-offer {
  color: var(--accent);
  font:
    9px 'IBM Plex Mono',
    monospace;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}
@media (min-width: 1500px) {
  .candidate-workspace {
    padding-inline: 64px;
  }
}
@media (max-width: 800px) {
  .folio-count {
    display: none;
  }
  .quiet-intro h1 {
    font-size: 50px;
  }
  .quiet-card h2 {
    font-size: 27px;
  }
  .candidate-workspace {
    padding-inline: 28px;
  }
}
@media (max-width: 680px) {
  .candidate-workspace {
    padding: 0 20px 28px;
  }
  .quiet-header {
    min-height: 108px;
  }
  .quiet-brand strong {
    font-size: 20px;
  }
  .quiet-brand > span {
    display: block;
    font-size: 9px;
    letter-spacing: 0.08em;
  }
  .header-signature {
    display: flex !important;
    gap: 0;
  }
  .header-signature > span:first-child {
    display: none;
  }
  .basilisk-emblem {
    width: 64px;
    height: 64px;
  }
  .quiet-intro {
    padding: 32px 0 26px;
  }
  .quiet-intro h1 {
    font-size: 43px;
    max-width: 330px;
  }
  .quiet-intro .eyebrow {
    font-size: 9px;
  }
  .shortlist-sort {
    font-size: 9px;
    gap: 12px;
    margin-bottom: 16px;
  }
  .shortlist-sort label {
    width: 100%;
    justify-content: space-between;
  }
  .shortlist-sort select {
    max-width: 210px;
  }
  .quiet-card {
    padding: 23px 22px 19px;
  }
  .quiet-card h2 {
    font-size: 28px;
    margin-top: 22px;
  }
  .quiet-card-meta {
    font-size: 9px;
  }
  .quiet-card-meta > span:last-child {
    font-size: 9px;
  }
  .card-offer-pair strong {
    font-size: 23px;
  }
  .card-dr-metrics {
    gap: 10px;
  }
  .card-dr-metrics dt {
    font-size: 9px;
  }
  .card-dr-metrics dd {
    font-size: 15px;
  }
  .candidate-workspace .modal-head {
    padding: 20px;
  }
  .candidate-workspace .modal-head h2 {
    font-size: 25px;
  }
  .candidate-workspace .modal-body {
    padding: 20px;
  }
  .offer-result {
    padding: 20px 17px;
  }
  .offer-result > strong {
    font-size: 51px;
  }
  .offer-result > span {
    font-size: 9px;
  }
  .offer-result > p {
    font-size: 10px;
    line-height: 1.7;
  }
  .demand-title {
    flex-wrap: wrap;
    gap: 0 10px;
  }
  .demand-title h3 {
    margin-bottom: 4px;
  }
  .earnings-grid > div {
    padding: 15px 12px;
  }
  .earnings-grid dd {
    font-size: 25px;
  }
  .earnings-grid dt {
    font-size: 9px;
  }
  .dossier-content .dossier-small {
    font-size: 10px;
  }
  .quiet-footer {
    font-size: 9px;
  }
}
@media (prefers-reduced-motion: reduce) {
  .quiet-card,
  .quiet-card h2 button,
  .quiet-actions button span {
    transition: none;
  }
  .quiet-card:hover {
    transform: none;
  }
}
/* Compact logo-only header; the shortlist begins directly below it. */
.candidate-workspace .quiet-header {
  min-height: 112px;
  margin-bottom: 26px;
}

/* Listing photography and shared-scale capacity comparisons. */
.property-photo {
  position: relative;
  margin: -27px -28px 24px;
  overflow: hidden;
  background: #18211b;
}
.property-photo img {
  display: block;
  width: 100%;
  height: 200px;
  object-fit: cover;
  filter: saturate(0.75);
}
.property-photo figcaption {
  position: absolute;
  right: 10px;
  bottom: 9px;
  padding: 5px 7px;
  background: #09110de6;
  border: 1px solid #ffffff24;
  font:
    8px 'IBM Plex Mono',
    monospace;
}
.property-photo a {
  color: #f0f1e7;
  text-decoration: none;
}
.property-photo a:hover {
  text-decoration: underline;
}
.photo-unavailable {
  height: 200px;
  display: grid;
  place-items: center;
  color: var(--muted);
  font-size: 12px;
}
.capacity-bars {
  display: grid;
  gap: 12px;
  margin: 25px 0;
}
.capacity-row > div:first-child {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 12px;
  margin-bottom: 6px;
  font:
    10px 'IBM Plex Mono',
    monospace;
  color: var(--muted);
}
.capacity-row strong {
  white-space: nowrap;
  font-weight: 400;
  color: #c1cebd;
}
.capacity-row.modeled strong {
  color: var(--accent);
}
.capacity-track {
  height: 5px;
  background: #ffffff09;
}
.capacity-track span {
  display: block;
  height: 100%;
  background: #74846e;
}
.modeled .capacity-track span {
  background: var(--accent);
}
.profit-bridge {
  margin: 28px 0;
  padding: 24px;
  border: 1px solid #3e5137;
  background: #0b140e;
}
.bridge-title {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 12px;
  margin-bottom: 24px;
}
.bridge-title h3 {
  margin: 0;
  font-size: 22px;
}
.bridge-title > span,
.bridge-basis {
  font:
    9px 'IBM Plex Mono',
    monospace;
  color: var(--muted);
}
.bridge-rows {
  display: grid;
  gap: 17px;
}
.bridge-label {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  font-size: 12px;
  margin-bottom: 7px;
}
.bridge-label strong {
  font:
    12px 'IBM Plex Mono',
    monospace;
  white-space: nowrap;
}
.bridge-track {
  position: relative;
  height: 13px;
  background: #ffffff05;
}
.bridge-track span {
  display: block;
  position: absolute;
  height: 100%;
  background: #768a6c;
}
.bridge-track i {
  position: absolute;
  height: 100%;
  width: 1px;
  background: #718366;
}
.bridge-row.deduction .bridge-track span {
  background: #b89f72;
}
.bridge-row.net .bridge-track span {
  background: var(--accent);
}
.bridge-row.net .bridge-label {
  color: var(--accent);
}
.bridge-row.loss .bridge-track span {
  background: #d8917c;
}
.bridge-row.loss .bridge-label {
  color: #e5ab96;
}
.bridge-basis {
  margin: 20px 0 0;
  line-height: 1.7;
}
.quiet-card:has(.property-photo)::before {
  z-index: 1;
}
@media (max-width: 680px) {
  .property-photo {
    margin-left: -22px;
    margin-right: -22px;
    margin-top: -23px;
  }
  .property-photo img,
  .photo-unavailable {
    height: 170px;
  }
  .profit-bridge {
    padding: 18px;
  }
  .bridge-title {
    flex-wrap: wrap;
    gap: 5px;
  }
  .capacity-row > div:first-child {
    font-size: 9px;
  }
}
.candidate-workspace .quiet-header > .basilisk-emblem {
  width: 72px;
  height: 72px;
}
.header-sort {
  display: flex;
  align-items: center;
  gap: 12px;
  font:
    10px 'IBM Plex Mono',
    monospace;
  color: var(--muted);
}
.header-sort select {
  width: auto;
  min-width: 175px;
  padding: 10px 12px;
  border: 1px solid #36492f;
  border-radius: 2px;
  background: #152019;
  color: var(--text);
  font:
    10px 'IBM Plex Mono',
    monospace;
}
@media (max-width: 680px) {
  .candidate-workspace .quiet-header {
    min-height: 94px;
    margin-bottom: 20px;
  }
  .candidate-workspace .quiet-header > .basilisk-emblem {
    width: 60px;
    height: 60px;
  }
  .header-sort {
    gap: 8px;
    font-size: 9px;
  }
  .header-sort select {
    min-width: 0;
    max-width: 190px;
    font-size: 10px;
  }
}
